/**
 * KaliTerminusEngine — Model-Driven Command Generation Engine.
 *
 * All command suggestions and reasoning are generated by the selected AI model
 * via Tauri IPC backend (HuggingFace Inference API).
 * Snippet search (# prefix) remains local for instant results.
 */

import { type AICommandSuggestion, createSuggestion, type Snippet } from '../models';

/**
 * Returns human-readable display name for a model ID.
 */
export function getModelDisplayName(modelId?: string): string {
  switch (modelId) {
    case 'granite-3.3-2b':
      return 'Granite 3.3 2B';
    case 'qwen2.5-coder-1.5b':
      return 'Qwen2.5-Coder 1.5B Instruct';
    case 'smollm2-360m':
      return 'SmolLM2 360M';
    case 'smollm2-3b':
      return 'SmolLM2 3B';
    case 'qwen3-1.7b':
      return 'Qwen3 1.7B';
    case 'qwen3-4b':
      return 'Qwen3 4B';
    case 'qwen3-8b':
      return 'Qwen3 8B';
    case 'ternary-bonsai-1.7b':
      return 'Ternary Bonsai 1.7B (Prism ML)';
    case 'ternary-bonsai-27b':
      return 'Ternary Bonsai 2-27B (Prism ML)';
    default:
      return 'Ternary Bonsai 1.7B (Prism ML)';
  }
}

// MARK: - Snippet Search Engine (# Prefix)

/**
 * Snippet Search Processor (# prefix):
 * Searches the user's snippet library matching title, description, category, tags, and command.
 */
export function searchSnippetSuggestion(rawQuery: string, snippets: Snippet[]): AICommandSuggestion {
  const query = rawQuery.trim().toLowerCase();

  if (!snippets || snippets.length === 0) {
    return createSuggestion(
      `# No snippets found in library. Use Snippets tool (⌘P) to create custom snippets`,
      'Snippet library is empty',
      'Snippet System (#)',
      0.5,
      'snippet',
      '#'
    );
  }

  if (!query) {
    const first = snippets[0];
    return createSuggestion(
      first.content,
      `Snippet: ${first.title} ${first.category ? `[${first.category}]` : ''}`,
      'Snippet System (#)',
      0.95,
      'snippet',
      '#',
      first.title
    );
  }

  let bestMatch: Snippet = snippets[0];
  let highestScore = -1;

  for (const snip of snippets) {
    let score = 0;
    const title = snip.title.toLowerCase();
    const content = snip.content.toLowerCase();
    const cat = snip.category ? snip.category.toLowerCase() : '';
    const tags = snip.tags.map((t) => t.toLowerCase());

    if (title === query) score += 100;
    else if (title.startsWith(query)) score += 60;
    else if (title.includes(query)) score += 40;

    if (tags.includes(query)) score += 50;
    else if (tags.some((t) => t.includes(query))) score += 30;

    if (cat.includes(query)) score += 35;
    if (content.includes(query)) score += 25;

    if (score > highestScore) {
      highestScore = score;
      bestMatch = snip;
    }
  }

  return createSuggestion(
    bestMatch.content,
    `Snippet: ${bestMatch.title} ${bestMatch.category ? `[${bestMatch.category}]` : ''}`,
    'Snippet System (#)',
    highestScore > 0 ? 0.95 : 0.6,
    'snippet',
    '#',
    bestMatch.title
  );
}

// MARK: - Tauri IPC Helper

/**
 * Gets the Tauri invoke function if running inside a Tauri app.
 * Returns null when running in browser preview mode.
 */
async function getTauriInvoke(): Promise<((cmd: string, args: Record<string, unknown>) => Promise<unknown>) | null> {
  try {
    const { invoke } = await import('@tauri-apps/api/core');
    return invoke;
  } catch {
    return null;
  }
}

// MARK: - Model-Driven Suggestion (Async)

/**
 * Generates a command suggestion from the selected AI model via Tauri backend.
 * This calls the HuggingFace Inference API through the Rust backend.
 */
export async function generateSuggestionAsync(
  input: string,
  suggestionModelId: string = 'ternary-bonsai-1.7b',
  targetEnv: string = 'local'
): Promise<AICommandSuggestion | null> {
  const text = input.trim();
  if (!text || text.length < 2) return null;

  const modelName = getModelDisplayName(suggestionModelId);
  const invoke = await getTauriInvoke();

  if (!invoke) {
    return createSuggestion(
      text,
      `Model inference requires native app (${modelName})`,
      modelName,
      0.5,
      'suggestion'
    );
  }

  try {
    const response = await invoke('generate_command_llm', {
      prompt: text,
      modelId: suggestionModelId,
      mode: 'suggestion',
      targetEnv,
    });

    let raw = typeof response === 'string' ? response.trim() : '';
    let result = cleanRawCommandOutput(raw);

    if (result && !isConversationalChatter(result)) {
      // Ensure result preserves full command line prefix
      if (!result.toLowerCase().startsWith(text.toLowerCase())) {
        const words = text.split(/\s+/);
        if (words.length > 1 && result.toLowerCase().startsWith(words[words.length - 1].toLowerCase())) {
          result = `${words.slice(0, -1).join(' ')} ${result}`;
        } else if (result.startsWith('-')) {
          result = `${text} ${result}`;
        }
      }
      if (result && result !== text && !isConversationalChatter(result)) {
        return createSuggestion(
          result,
          `AI suggestion for: "${text}"`,
          modelName,
          0.9,
          'suggestion'
        );
      }
    }
  } catch (err) {
    const errorDetails = err instanceof Error ? err.message : String(err);
    console.warn(`[KaliTerminus] Suggestion model error (${modelName}):`, errorDetails);
    if (errorDetails.includes('not downloaded') || errorDetails.includes('Model Manager')) {
      return createSuggestion(
        text,
        `Model not downloaded: open Settings -> Model Manager to download ${modelName}`,
        modelName,
        0.2,
        'suggestion'
      );
    }
    return null;
  }

  return null;
}

/**
 * Detects whether a string is conversational prose rather than a shell command.
 */
export function isConversationalChatter(text: string): boolean {
  const lower = text.trim().toLowerCase();
  const starters = [
    'okay', 'ok', 'sure', 'here', 'to ', 'i ', 'you ', 'we ', "let's", 'let ',
    'the ', 'this ', 'certainly', 'note:', 'first', 'in order to', 'how to',
    'please', 'hello', 'hi ', 'as an', 'what', 'why', 'when', 'there', 'based on',
    'output:', 'command:', 'explanation:', 'step', 'user', 'remember',
  ];
  if (starters.some((s) => lower.startsWith(s))) return true;
  return (
    lower.includes('help the user') ||
    lower.includes('complete the') ||
    lower.includes('shell command') ||
    lower.includes('i need to') ||
    lower.includes('you can use') ||
    lower.includes('is used to') ||
    lower.includes('stands for')
  );
}

/**
 * Strips tool call tokens (<call:exec>...</call:exec>, <tool_call>), raw JSON,
 * markdown code fences (```bash, ```), backticks, and unwanted punctuation from model output.
 */
export function cleanRawCommandOutput(raw: string): string {
  let cleaned = raw.trim();
  if (!cleaned) return '';

  // 0. Strip <think>...</think> from DeepSeek R1
  if (cleaned.includes('<think>')) {
    const endIdx = cleaned.indexOf('</think>');
    if (endIdx !== -1) {
      cleaned = cleaned.slice(endIdx + 8).trim();
    } else {
      return '';
    }
  }

  // 1. Tool call wrappers: <call:exec>{"command": "..."}</call:exec>
  const toolCallMatch = cleaned.match(/<call:[^>]+>([\s\S]*?)<\/call:[^>]+>/i) ||
                        cleaned.match(/<tool_call>([\s\S]*?)<\/tool_call>/i);
  if (toolCallMatch) {
    try {
      const parsed = JSON.parse(toolCallMatch[1].trim());
      if (parsed.command && parsed.command !== 'command()' && parsed.command !== 'none') {
        return cleanRawCommandOutput(parsed.command);
      }
    } catch {
      const cmdMatch = toolCallMatch[1].match(/"command":\s*"([^"]+)"/);
      if (cmdMatch && cmdMatch[1] !== 'command()' && cmdMatch[1] !== 'none') {
        return cleanRawCommandOutput(cmdMatch[1].replace(/\\"/g, '"'));
      }
    }
  }

  // 2. Raw JSON blob {"command": "..."}
  if (cleaned.startsWith('{') && cleaned.includes('"command"')) {
    try {
      const parsed = JSON.parse(cleaned);
      if (parsed.command && parsed.command !== 'command()' && parsed.command !== 'none') {
        return cleanRawCommandOutput(parsed.command);
      }
    } catch {
      const cmdMatch = cleaned.match(/"command":\s*"([^"]+)"/);
      if (cmdMatch && cmdMatch[1] !== 'command()' && cmdMatch[1] !== 'none') {
        return cleanRawCommandOutput(cmdMatch[1].replace(/\\"/g, '"'));
      }
    }
  }

  // 3. Discard dummy placeholders like "command()"
  if (cleaned === 'command()' || cleaned === '<call:exec>{"command": "command()"}</call:exec>') {
    return '';
  }

  // 4. Strip markdown code fences anywhere (```bash, ```sh, ```)
  cleaned = cleaned.replace(/^```[a-zA-Z0-9_-]*/gm, '').replace(/```$/gm, '').trim();
  cleaned = cleaned.replace(/^[$>]\s*/, '').trim();

  // 5. Strip any leftover XML/call tags
  cleaned = cleaned.replace(/<\/?call:[^>]*>/gi, '').replace(/<\/?tool_call>/gi, '').trim();

  // 6. Strip surrounding single quotes, double quotes, or backticks
  if (
    (cleaned.startsWith('`') && cleaned.endsWith('`') && cleaned.length >= 2) ||
    (cleaned.startsWith('"') && cleaned.endsWith('"') && cleaned.length >= 2) ||
    (cleaned.startsWith("'") && cleaned.endsWith("'") && cleaned.length >= 2)
  ) {
    cleaned = cleaned.slice(1, -1).trim();
  }

  // 7. Strip trailing backslashes that cause shell continuation lines
  cleaned = cleaned.replace(/\\+$/, '').trim();

  return cleaned;
}

// MARK: - Model-Driven Reasoning (Async)

/**
 * Generates a reasoning response from the selected reasoning model via Tauri backend.
 * Extracts rich explanations, thought steps, and executable shell commands.
 */
export async function generateReasoningAsync(
  input: string,
  reasoningModelId: string = 'ternary-bonsai-27b',
  targetEnv: string = 'local'
): Promise<AICommandSuggestion | null> {
  const query = input.trim();
  if (!query) return null;

  const modelName = getModelDisplayName(reasoningModelId);
  const modelLabel = `${modelName} (@)`;
  const invoke = await getTauriInvoke();

  if (!invoke) {
    return createSuggestion(
      `# Reasoning requires native desktop app with Tauri IPC backend.\n# Running in browser preview (npm run dev) cannot call native AI models.\n# Start app with: npm run tauri dev`,
      `Native app required (${modelName})`,
      modelLabel,
      0.5,
      'reasoning',
      '@',
      undefined,
      ['Native desktop app with Tauri IPC backend is required to run offline models.'],
      [],
      query
    );
  }

  try {
    const response = await invoke('generate_command_llm', {
      prompt: query,
      modelId: reasoningModelId,
      mode: 'reasoning',
      targetEnv,
    });

    const result = typeof response === 'string' ? response.trim() : '';
    if (result) {
      const allLines = result.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
      const commands: string[] = [];

      for (const line of allLines) {
        if (line.startsWith('#') || line.startsWith('//') || line.startsWith('```')) {
          continue;
        }
        const cleanCmd = cleanRawCommandOutput(line);
        if (cleanCmd && cleanCmd !== 'command()' && !isConversationalChatter(cleanCmd)) {
          commands.push(cleanCmd);
        }
      }

      const primaryCommand = commands.length > 1 ? commands.join(' && ') : (commands[0] || cleanRawCommandOutput(result));
      if (!primaryCommand || isConversationalChatter(primaryCommand)) {
        return null;
      }

      return createSuggestion(
        primaryCommand,
        `AI command for: "${query}"`,
        modelLabel,
        0.95,
        'reasoning',
        '@',
        undefined,
        [],
        [primaryCommand],
        query
      );
    }
  } catch (err) {
    const errorDetails = err instanceof Error ? err.message : String(err);
    const failInfo = errorDetails.includes('not downloaded')
      ? `Model '${modelName}' is not downloaded. Open Settings → Model Manager to download it for offline use.`
      : `Reasoning inference failed: ${errorDetails}`;

    return createSuggestion(
      '',
      `Inference failed (${modelName})`,
      modelLabel,
      0.2,
      'reasoning',
      '@',
      undefined,
      [failInfo],
      [],
      query
    );
  }

  return null;
}

// MARK: - Public API (Unified Router)

/**
 * Unified Suggestion Router (synchronous — only handles snippets):
 * - '# query' -> Snippet System (instant local search)
 * - Everything else returns null (use async functions for model calls)
 */
export function generateWithRouting(
  input: string,
  snippets: Snippet[] = [],
  _reasoningModelId: string = 'ternary-bonsai-27b',
  _suggestionModelId: string = 'ternary-bonsai-1.7b'
): AICommandSuggestion | null {
  const text = input.trim();
  if (!text) return null;

  // Snippet mode (# prefix) — instant local search
  if (text.startsWith('#')) {
    return searchSnippetSuggestion(text.slice(1), snippets);
  }

  // All other suggestions come from the async model functions
  return null;
}

/**
 * Unified async router that sends all queries to the actual AI model.
 * - '@ query' -> Reasoning Model via Tauri IPC
 * - '# query' -> Snippet System (local instant)
 * - '<text>'  -> Suggestion Model via Tauri IPC
 */
export async function generateWithModelAsync(
  input: string,
  snippets: Snippet[] = [],
  reasoningModelId: string = 'ternary-bonsai-27b',
  suggestionModelId: string = 'ternary-bonsai-1.7b',
  targetEnv: string = 'local'
): Promise<AICommandSuggestion | null> {
  const text = input.trim();
  if (!text) return null;

  // 1. Reasoning mode (@ prefix) — model-driven
  if (text.startsWith('@')) {
    return generateReasoningAsync(text.slice(1), reasoningModelId, targetEnv);
  }

  // 2. Snippet mode (# prefix) — local instant
  if (text.startsWith('#')) {
    return searchSnippetSuggestion(text.slice(1), snippets);
  }

  // 3. Normal command suggestion — model-driven
  return generateSuggestionAsync(text, suggestionModelId, targetEnv);
}

/**
 * Two-tier generate: calls the AI model via Tauri IPC.
 * This replaces the old local engine entirely.
 */
export async function generateWithLLM(
  input: string,
  _invokeTauri?: (cmd: string, args: Record<string, unknown>) => Promise<string>,
  snippets: Snippet[] = [],
  reasoningModelId: string = 'ternary-bonsai-27b',
  suggestionModelId: string = 'ternary-bonsai-1.7b',
  targetEnv: string = 'local'
): Promise<AICommandSuggestion | null> {
  return generateWithModelAsync(input, snippets, reasoningModelId, suggestionModelId, targetEnv);
}

/**
 * Synchronous generate kept for backward compatibility (ModelManagerContent playground).
 * Returns null for everything except snippets — callers should migrate to async.
 */
export function generate(
  input: string,
  _reasoningModelId: string = 'ternary-bonsai-27b',
  _suggestionModelId: string = 'ternary-bonsai-1.7b'
): AICommandSuggestion | null {
  const text = input.trim();
  if (!text) return null;

  if (text.startsWith('#')) {
    return searchSnippetSuggestion(text.slice(1), []);
  }

  return null;
}

/**
 * Synchronous generateReasoningCommand kept for backward compatibility.
 * Returns a placeholder — callers should migrate to generateReasoningAsync.
 */
export function generateReasoningCommand(rawQuery: string, modelId: string = 'deepseek-r1-1.5b'): AICommandSuggestion {
  const query = rawQuery.trim();
  const modelName = getModelDisplayName(modelId);
  const modelLabel = `${modelName} (@)`;

  if (!query) {
    return createSuggestion(
      `# Type your question or reasoning task after '@'\n# The ${modelName} model will generate commands for you\n# Example: @ check node version\n# Example: @ kill port 8080`,
      'Reasoning Mode: AI model generates executable commands',
      modelLabel,
      1.0,
      'reasoning',
      '@'
    );
  }

  return createSuggestion(
    `# Generating with ${modelName}...\n# Query: ${query}`,
    `Reasoning: Waiting for ${modelName} model response`,
    modelLabel,
    0.5,
    'reasoning',
    '@'
  );
}
